contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    // Attempt to withdraw more than C's balance; amount is the attempted withdrawal value
    function run(uint amount) public payable {
        // ensure this test contract has enough ETH if it needs to fund C first
        // but we do not require any funding here; we only observe current C balance
        uint beforeBal = address(c).balance;
        uint beforeCount = c.depositsCount(); if (__ESBMC_reverted()) return;

        bool reverted;
        // call withdraw as a top-level statement, capturing revert via try/catch
        c.withdraw(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterBal = address(c).balance;
        uint afterCount = c.depositsCount(); if (__ESBMC_reverted()) return;

        // General rule: if amount > beforeBal then the call must revert and leave state unchanged
        assert((amount > beforeBal) ? (reverted && afterBal == beforeBal && afterCount == beforeCount) : true);
    }
    receive() external payable { }
}

